    public static function findTool(string $slug): ?array
    {
        foreach (self::getTools() as $catSlug => $category) {
            if (isset($category['tools'][$slug])) {
                return array_merge($category['tools'][$slug], [
                    'category' => $catSlug,
                    'categoryName' => $category['name'],
                ]);
            }
        }
        return null;
    }

    public static function getAllToolSlugs(): array
    {
        $slugs = [];
        foreach (self::getTools() as $catSlug => $category) {
            foreach ($category['tools'] as $toolSlug => $tool) {
                $slugs[] = ['category' => $catSlug, 'slug' => $toolSlug];
            }
        }
        return $slugs;
    }

    public static function getToolsByCategory(string $categorySlug): array
    {
        return self::getTools()[$categorySlug]['tools'] ?? [];
    }

    public static function forCategory(string $categorySlug): array
    {
        return self::getToolsByCategory($categorySlug);
    }

    public static function all(): array
    {
        return self::getTools();
    }

    public static function getCategoryInfo(string $categorySlug): ?array
    {
        $tools = self::getTools();
        if (!isset($tools[$categorySlug])) return null;
        $cat = $tools[$categorySlug];
        return [
            'name' => $cat['name'],
            'icon' => $cat['icon'],
            'description' => $cat['description'],
            'count' => count($cat['tools']),
        ];
    }

    public static function getPopularTools(int $count = 8): array
    {
        $baseUrl = config('site.url');
        $popular = [];
        $categories = config('site.categories');
        foreach (self::getTools() as $catSlug => $catData) {
            $tools = $catData['tools'] ?? [];
            $i = 0;
            foreach ($tools as $slug => $tool) {
                if ($i >= 2) break;
                $popular[] = [
                    'title' => $tool['title'],
                    'description' => $tool['description'] ?? '',
                    'url' => $baseUrl . '/' . $catSlug . '/' . $slug,
                    'category' => $categories[$catSlug]['name'] ?? ($catData['name'] ?? ucfirst($catSlug)),
                    'categorySlug' => $catSlug,
                ];
                $i++;
                if (count($popular) >= $count) break 2;
            }
        }
        return array_slice($popular, 0, $count);
    }

    public static function getCategoryLinks(): array
    {
        $baseUrl = config('site.url');
        $links = [];
        $categories = config('site.categories');
        foreach (self::getTools() as $catSlug => $catData) {
            $toolCount = count($catData['tools'] ?? []);
            if ($toolCount === 0) continue;
            $links[] = [
                'name' => $categories[$catSlug]['name'] ?? ($catData['name'] ?? ucfirst($catSlug)),
                'url' => $baseUrl . '/' . $catSlug,
                'count' => $toolCount,
                'toolCount' => $toolCount,
                'slug' => $catSlug,
            ];
        }
        return $links;
    }

    public static function getRelatedTools(string $currentCategory, string $currentSlug, int $sameCategoryCount = 4, int $crossCategoryCount = 4): array
    {
        $baseUrl = config('site.url');
        $categories = config('site.categories');
        $allTools = self::getTools();

        $sameCategory = [];
        $crossCategory = [];

        if (isset($allTools[$currentCategory])) {
            $tools = $allTools[$currentCategory]['tools'] ?? [];
            $i = 0;
            foreach ($tools as $slug => $tool) {
                if ($slug === $currentSlug) continue;
                if ($i >= $sameCategoryCount) break;
                $sameCategory[] = [
                    'title' => $tool['title'],
                    'description' => $tool['description'] ?? '',
                    'url' => $baseUrl . '/' . $currentCategory . '/' . $slug,
                    'category' => $categories[$currentCategory]['name'] ?? ucfirst($currentCategory),
                ];
                $i++;
            }
        }

        foreach ($allTools as $catSlug => $catData) {
            if ($catSlug === $currentCategory) continue;
            $tools = $catData['tools'] ?? [];
            if (empty($tools)) continue;
            $firstSlug = array_key_first($tools);
            $tool = $tools[$firstSlug];
            $crossCategory[] = [
                'title' => $tool['title'],
                'description' => $tool['description'] ?? '',
                'url' => $baseUrl . '/' . $catSlug . '/' . $firstSlug,
                'category' => $categories[$catSlug]['name'] ?? ($catData['name'] ?? ucfirst($catSlug)),
            ];
            if (count($crossCategory) >= $crossCategoryCount) break;
        }

        return ['sameCategory' => $sameCategory, 'crossCategory' => $crossCategory];
    }
}